18	   * The price the shopper pays today, already formatted by the caller (e.g. "$450.00").
19	   * Optional: `ZimmProductPrice` renders nothing when absent or empty, so the flex gap
20	   * collapses cleanly.
21	   * — On sale: this is the *sale* price (the "Now" figure).
22	   * — Full price: this is the only price shown.
23	   */
24	  currentPrice?: string;
25	  /**
26	   * The original full price before the sale, already formatted (e.g. "$795.00").
27	   * Only supplied when the product is on sale (PRC-09). When present, `ZimmProductPrice`
28	   * switches to the Was/Now treatment — "Was {originalPrice} Now {currentPrice}".
29	   * Absent for full-price items.
30	   */
31	  originalPrice?: string;
32	  /** When true, the price atom renders an empty container while a variant re-fetch is in flight. */
